nextflow_process {

    name "Test Process SMUDGEPLOT_ALL"
    script "../main.nf"
    process "SMUDGEPLOT_ALL"

    tag "modules"
    tag "modules_nfcore"
    tag "smudgeplot"
    tag "smudgeplot/all"
    tag "smudgeplot/hetmers"
    tag "fastk/fastk"

    setup {
        run("FASTK_FASTK") {
            script "modules/nf-core/fastk/fastk/main.nf"
            config "./nextflow.config"
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file("https://tolit.cog.sanger.ac.uk/test-data/Acropora_cervicornis/genomic_data/m84093_241116_151316_s2.hifi_reads.bc2028.subset.fasta.gz", checkIfExists: true)
                ]
                """
            }
        }

        run("SMUDGEPLOT_HETMERS") {
            script "modules/nf-core/smudgeplot/hetmers/main.nf"
            config "./nextflow.config"
            process {
                """
                input[0] = FASTK_FASTK.out.ktab
                """
            }
        }
    }
// The below test has been disabled due to a bug with Smudgeplot detailed here:
// https://github.com/KamilSJaron/smudgeplot/issues/263
// Effectively, the tool currently only supports large and complete data and fixes will be
// added in the next release
