    //     when {
    //         process {
    //             """
    //             input[0] = SMUDGEPLOT_HETMERS.out.kmer_cov
    //             """
    //         }
    //     }

    //     then {
    //         assertAll(
    //             { assert process.success },
    //             { assert snapshot(sanitizeOutput(process.out)).match() }
    //         )
    //     }
    // }

    test("Acropora_cervicornis - reads - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = SMUDGEPLOT_HETMERS.out.kmer_cov
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

